package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.service.content.*;
import com.lianxibu.site.service.jobs.JobsService.*;
import com.lianxibu.site.service.jobs.ResultApplicationService.*;
import java.util.*;
import org.junit.jupiter.api.*;

/** Real original ad hoc generation, claim/send, unknown, owner confirmation and no-content handler. */
class NonContentManualStoreTest {
    ResultJdbcStoreTest f;ResultJdbcStore store;ResultApplicationService core;Input input;String hash;
    final com.lianxibu.site.service.identity.IdentityService.Actor owner=new com.lianxibu.site.service.identity.IdentityService.Actor("fictional-owner","owner");
    ResultJdbcStoreTest fixture(){var value=new NonContentManualProofFixture();value.initialize(true);return value;}
    @BeforeEach void setup(){
        f=fixture();f.jdbc.execute("ALTER TABLE article_revisions ADD validity_revision BIGINT NOT NULL DEFAULT 0");f.jdbc.execute("ALTER TABLE article_revisions ADD article_id VARCHAR(64)");f.jdbc.execute("DROP TABLE IF EXISTS articles");f.jdbc.execute("CREATE TABLE articles(id VARCHAR(64) PRIMARY KEY)");f.jdbc.update("INSERT INTO articles VALUES('fictional-article')");f.jdbc.update("UPDATE article_revisions SET article_id='fictional-article'");for(String column:List.of("validity_revision BIGINT","reverses_disposition_id VARCHAR(64)","error_code VARCHAR(64)"))f.jdbc.execute("ALTER TABLE jobs ADD "+column);
        new TransportUnknownService(f.writes,new JdbcTransportUnknown(f.source),f.clock,"fictional-epoch").release(f.identity,TransportUnknownService.Cause.TRANSPORT_UNKNOWN,f.action("fictional-ad-hoc-unknown"));var envelope=CanonicalJson.parse(f.raw());hash=envelope.get("result_hash").textValue();var root=new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT);var action=new JobAction(root.revision(),"resolve_external","Fictional verified temporary answer",f.identity.attemptId(),null,null,"succeeded",List.of("fictional-evidence"),new ValidatedResult("1",f.identity.inputHash(),envelope.get("payload"),hash),null);assertTrue(new OwnerJobResolveExternalService(f.source,f.tx,f.writes,f.clock).resolve(owner,ResultJdbcStoreTest.ROOT,action,"fictional-ad-hoc-confirm").rootResultRetained());
        var contents=new ContentReadService(new JdbcContentReads(f.source),f.tx,ContentReadService.denyUnverifiedReferences());var generated=new GeneratedContentService(new JdbcGeneratedContents(f.source),f.clock);var ledger=new VersionValidityLedgerService(new JdbcVersionValidity(f.source),new FrozenContentVersionService(new JdbcFrozenContentVersions(f.source)),new com.lianxibu.site.service.articles.EvidenceValidityService(new com.lianxibu.site.repository.articles.JdbcEvidenceValidity(f.source)),new ContentReviewWriteService(new JdbcReviewPublication(f.source),generated,f.clock),f.clock,owner.userId());
        store=new ResultJdbcStore(f.source,f.identity,contents,target->ledger.exactVersionExists(target)&&ledger.validity(target).effectiveValid(),f.clock,owner.userId(),true);input=store.input();core=core(store);assertNull(input.expectedContentRevision());
    }
    ResultApplicationService core(Store provider){Handler unused=(i,r,c,m)->{throw new AssertionError("unexpected result branch");};return new ResultApplicationService(f.writes,provider,Map.of("dedup",unused,"value",unused,"analysis",unused,"report",unused,"ad_hoc",new AdHocResultHandler(new JdbcFrozenInputs(f.source)::read)));}
    long revision(){return new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).revision();}
    Result apply(String key,long expected,Long content){return core.applyManual(input,hash,expected,content,"Fictional explicit temporary application",true,f.action(key));}
    void invalidate(){var helper=new ConfirmedContentApplicationTest();helper.f=f;helper.invalidateReference();}
    @Test void NativeNoContentApplicationHasNullCasAndReceiptAndLeavesNewSlotUntouched(){long before=revision();f.jdbc.update("UPDATE worker_lock SET slot_state='occupied',holder='fictional-new-holder',job_id='fictional-new-attempt',slot_revision=71,fencing_token=71");var slot=new JdbcWorkerState(f.source).slot();var result=apply("fictional-ad-hoc-apply",before,null);assertEquals(Status.APPLIED,result.status());assertNull(result.contentId());assertNull(result.contentRevision());assertEquals(before+1,revision());assertEquals("APPLIED",new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).application());var receipt=new JdbcResultState(f.source).receipt("fictional-ad-hoc-apply",owner.userId(),ResultJdbcStoreTest.ROOT,f.identity.attemptId());assertTrue(receipt.get("content_id").isNull());assertTrue(receipt.get("content_revision").isNull());assertFalse(receipt.has("content_version"));assertEquals(0,f.count("contents"));assertEquals(slot,new JdbcWorkerState(f.source).slot());assertEquals(1,f.sends);assertEquals(1,new JdbcJobRecords(f.source).byId(ResultJdbcStoreTest.ROOT).callCount());}
    @Test void InventedZeroContentRevisionCannotReplaceNullNoContentCas(){long before=revision();assertEquals(ManualRefusal.REVISION_CONFLICT,assertThrows(ManualRejected.class,()->apply("fictional-fake-content-cas",before,0L)).refusal());assertEquals(before,revision());assertEquals(0,f.count("contents"));}
    @Test void OriginalNoContentReceiptReplaysAfterCurrentReferenceInvalidationAndAckLoss(){long before=revision();f.tx.ackLost=true;var result=apply("fictional-ad-hoc-ack",before,null);invalidate();long count=f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class);assertEquals(result,apply("fictional-ad-hoc-ack",before,null));assertEquals(count,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));assertEquals(0,f.count("contents"));}
    @Test void CurrentNativeInvalidReferenceAndLaterGenerationStillBlockApplication(){long before=revision();invalidate();assertEquals(ManualRefusal.INVALID_EVIDENCE,assertThrows(ManualRejected.class,()->apply("fictional-ad-hoc-invalid",before,null)).refusal());assertEquals(before,revision());}
    @Test void OlderGenerationCannotAcquireNoContentApplicationPermission(){long before=revision();f.writes.execute(f.action("fictional-ad-hoc-next-generation"),key->null,a->{new JdbcJobRecords(f.source).ensureIntent(new JdbcJobRecords.Intent("fictional-ad-hoc-next-intent","fictional-ad-hoc",2,"ad_hoc_ai",java.time.LocalDate.of(2026,1,1)),f.clock.instant());return true;});assertEquals(ManualRefusal.SUPERSEDED,assertThrows(ManualRejected.class,()->apply("fictional-ad-hoc-superseded",before,null)).refusal());assertEquals(before,revision());}
    @Test void MissingOriginalClaimOrDamagedRetainedPartCannotBecomeManualProof(){final long before=revision();f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='worker_claim'",new byte[32]);assertThrows(IllegalStateException.class,()->apply("fictional-ad-hoc-damaged-claim",before,null));assertEquals(before,revision());setup();final long damagedRevision=revision();f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE purpose='result'",new byte[32]);final long expected=damagedRevision;assertThrows(IllegalStateException.class,()->apply("fictional-ad-hoc-damaged-result",expected,null));assertEquals(expected,revision());}
}
